const gutil = require('gulp-util');
const PluginError = gutil.PluginError;
const through = require('through2');

const pluginName = 'gulp-webp-css';

module.exports = function(extensions){
    var extensions = extensions || ['.jpg','.png','.jpeg','JPG'];
    return through.obj(function(file, enc, cb) {
        if (file.isNull()) {
            cb(null, file);
            return;
        }

        if (file.isStream()) {
            cb(new PluginError(pluginName, 'Streaming not supported'));
            return;
        }

        try {
            var supportsLine = function(selector,url){
                var line = selector + '{background-image: url(' + url + ');}';
                return line;
            }
            var supportsRender = function (rulesArr) {
                return '@supports (-webkit-appearance:none){' + "\n" + rulesArr.join("\n") + "\n" + '}'
            }
            var currentSelector;
            var supportsArrStr = [];
            const data = file.contents.toString()
                    .split('\n')
                    .map(function(line){
                        // Текущий селектор
                        var pos = line.indexOf('{');
                        if (pos + 1){
                            currentSelector = line.substring(0,pos);
                        }

                        // Проверяем есть ли свойство background url
                        if((line.indexOf("background") + 1) && (line.indexOf('url(') + 1)){
                            // Новый урл с .webp
                            var Re = /url\((\S+)\)/ig;
                            var regexpArray = Re.exec(line);
                            var newUrl = regexpArray[1];
                            // Если в урле есть .webp, пропускаем
                            if (newUrl.indexOf('.webp') + 1) return line;
                            // Заменяем все расширения на .webp
                            for(k in extensions){
                                newUrl = newUrl.replace(extensions[k],'.webp')
                            }
                            // Формируем строку и пушим в массив дополнений
                            supportsArrStr.push(supportsLine(currentSelector,newUrl));
                        }
                        return line;
                    })
                    .join('')
                    .concat(supportsRender(supportsArrStr));
            file.contents = new Buffer(data);
            this.push(file);
        } catch (err) {
            this.emit('error', new PluginError(pluginName, err));
        }

        cb();
    });
};